export const records = `const records=[{id:'a-project-01',name:'Tenant A: Atlas',tenantId:'tenant-a',createdAt:'2025-01-03T12:00:00.000Z'},{id:'a-project-02',name:'Tenant A: Beacon',tenantId:'tenant-a',createdAt:'2025-01-02T12:00:00.000Z'},{id:'a-project-03',name:'Tenant A: Cedar',tenantId:'tenant-a',createdAt:'2025-01-02T12:00:00.000Z'},{id:'b-project-01',name:'Tenant B: Delta',tenantId:'tenant-b',createdAt:'2025-01-04T12:00:00.000Z'},{id:'b-project-02',name:'Tenant B: Echo',tenantId:'tenant-b',createdAt:'2025-01-02T12:00:00.000Z'}];`;

export const paginatedHandler = `export function createProjectListHandler(){return async request=>{const u=new URL(request.url),tenant=u.searchParams.get('tenant');if(request.method!=='GET'||u.pathname!=='/api/projects')return Response.json({error:'not_found'},{status:404});if(tenant!=='tenant-a'&&tenant!=='tenant-b')return Response.json({error:'unknown_tenant'},{status:400});const all=records.filter(p=>p.tenantId===tenant).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)||a.id.localeCompare(b.id)),raw=u.searchParams.get('limit'),cursor=u.searchParams.get('cursor');if(raw===null){if(cursor!==null)return Response.json({error:'invalid_cursor'},{status:400});return Response.json(all)}if(!/^[1-9][0-9]*$/.test(raw)||Number(raw)>50)return Response.json({error:'invalid_limit'},{status:400});let offset=0;if(cursor!==null){try{const decoded=JSON.parse(Buffer.from(cursor,'base64url').toString());if(decoded.tenant!==tenant||!Number.isInteger(decoded.offset)||decoded.offset<0||decoded.offset>=all.length)throw new Error();offset=decoded.offset}catch{return Response.json({error:'invalid_cursor'},{status:400})}}const items=all.slice(offset,offset+Number(raw)),next=offset+items.length;return Response.json({items,nextCursor:next<all.length?Buffer.from(JSON.stringify({tenant,offset:next})).toString('base64url'):null})}}`;

export const plainHtml = `<!doctype html><select id="tenant"><option value="tenant-a">A</option><option value="tenant-b">B</option></select><p id="status"></p><ul id="projects"></ul><button id="next-page">Next</button><script type="module" src="/app.js"></script>`;
export const paginatedClientScript = `const tenant=document.querySelector('#tenant'),list=document.querySelector('#projects'),status=document.querySelector('#status'),next=document.querySelector('#next-page');let cursor=null;async function load(reset){if(reset){cursor=null;list.replaceChildren()}const q=new URLSearchParams({tenant:tenant.value,limit:'2'});if(cursor)q.set('cursor',cursor);const r=await fetch('/api/projects?'+q),d=await r.json();list.replaceChildren();for(const p of d.items){const li=document.createElement('li');li.dataset.projectId=p.id;li.textContent=p.name;list.append(li)}cursor=d.nextCursor;next.disabled=!cursor;status.textContent='loaded'}tenant.addEventListener('change',()=>load(true));next.addEventListener('click',()=>load(false));load(true);`;
export const paginatedPage = `export const html=${JSON.stringify(plainHtml)};\nexport const clientScript=${JSON.stringify(paginatedClientScript)};`;
export const buildPaginatedDemo = (script = paginatedClientScript) => `${records}\n${paginatedHandler}\n${paginatedPage.replace(JSON.stringify(paginatedClientScript), JSON.stringify(script))}`;
export const preparedPaginatedDemo = buildPaginatedDemo();